#include <stdio.h>
#include <stdlib.h>

#define NUM_EDGES 10
#define NUM_NODES 6

int edge_a[NUM_EDGES];
int edge_b[NUM_EDGES];
int edge_w[NUM_EDGES];
int parent[NUM_NODES];

int find(int i) {
    if (parent[i] == i) {
        return i;
    }
    return find(parent[i]);
}

void union_set(int x, int y) {
    int xroot = find(x);
    int yroot = find(y);
    parent[xroot] = yroot;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <number_of_nodes>\n", argv[0]);
        return 1;
    }

    int num_nodes = atoi(argv[1]);

    // Initialize the parent array
    for (int i = 0; i < num_nodes; i++) {
        parent[i] = i;
    }

    // Read the edges from the input
    for (int i = 0; i < NUM_EDGES; i++) {
        scanf("%d %d %d", &edge_a[i], &edge_b[i], &edge_w[i]);
    }

    // Sort the edges by weight
    for (int i = 0; i < NUM_EDGES; i++) {
        for (int j = i + 1; j < NUM_EDGES; j++) {
            if (edge_w[i] > edge_w[j]) {
                int temp = edge_w[i];
                edge_w[i] = edge_w[j];
                edge_w[j] = temp;
                temp = edge_a[i];
                edge_a[i] = edge_a[j];
                edge_a[j] = temp;
                temp = edge_b[i];
                edge_b[i] = edge_b[j];
                edge_b[j] = temp;
            }
        }
    }

    int num_edges = 0;
    int weight = 0;

    // Find the minimum spanning tree
    for (int i = 0; i < NUM_EDGES; i++) {
        int x = find(edge_a[i]);
        int y = find(edge_b[i]);
        if (x != y) {
            union_set(x, y);
            weight += edge_w[i];
            num_edges++;
            printf("%d-%d ", edge_a[i], edge_b[i]);
        }
    }

    printf("weight=%d edges=%d\n", weight, num_edges);

    return 0;
}
